"use client";
import { useState } from 'react';
import { useCart } from '@paykit/react';
import { formatUsdt, type Product } from '@paykit/js';
import './paykit-ui.css';

export function CustomProductCard({ product, className = '' }: { product: Product; className?: string }) {
  const cart = useCart(product.merchantSlug);
  const quantity = cart.items.find((item) => item.productId === product.id)?.quantity ?? 0;
  const [bumps, setBumps] = useState(0);
  const add = () => { cart.add(product); setBumps((n) => n + 1); };
  return <article className={`pkc-card pkc-product ${className}`}>
    <div className="pkc-product__art">
      {product.imageUrl ? <img src={product.imageUrl} alt="" /> : <Sprite seed={product.name} />}
      {!product.active && <span className="pkc-soldout">Sold out</span>}
    </div>
    <div className="pkc-product__body">
      <h3 className="pkc-title">{product.name}</h3>
      {product.description && <p className="pkc-muted">{product.description}</p>}
    </div>
    <div className="pkc-product__foot">
      <span className="pkc-product__price">{formatUsdt(product.price)} <small>USDT</small></span>
      {quantity === 0
        ? <button className="pkc-button" disabled={!product.active} onClick={add}>{product.active ? 'Add to cart' : 'Unavailable'}</button>
        : <span className="pkc-stepper" role="group" aria-label={`${product.name} quantity`}>
          <button type="button" aria-label="Remove one" onClick={() => cart.setQuantity(product.id, quantity - 1)}>−</button>
          <output aria-live="polite"><span key={quantity}>{quantity}</span></output>
          <button type="button" aria-label="Add one" disabled={quantity >= 99} onClick={add}>+</button>
        </span>}
    </div>
    {bumps > 0 && <span key={bumps} className="pkc-plus" aria-hidden="true">+1</span>}
  </article>;
}

/** A symmetric pixel sprite drawn from the product name, for products without a photo. */
function Sprite({ seed }: { seed: string }) {
  let h = 2166136261;
  for (const c of seed) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  const palette = ['transparent', 'var(--pk-progress, #00a3ff)', 'var(--pk-progress-soft, #7ccfff)', 'var(--pk-ink, #0a0a0a)'];
  const cells: string[] = [];
  for (let y = 0; y < 7; y++) for (let x = 0; x < 7; x++) {
    const m = Math.min(x, 6 - x);
    const v = (h >>> ((y * 4 + m) % 29)) & 3;
    cells.push(palette[y === 0 || y === 6 ? (v === 3 ? 0 : v & 1) : v]);
  }
  return <span className="pkc-sprite" aria-hidden="true">{cells.map((color, i) => <i key={i} style={{ background: color }} />)}</span>;
}

/* Own this stylesheet. Money and signing logic stays in @paykit/react hooks.
 * Theme with the --pk-* variables. Optional: --pk-display (headings) and --pk-pixel (labels). */
.pkc-card, .pkc-wallet {
  --_ink: var(--pk-ink, #0a0a0a); --_muted: var(--pk-muted, #6b7178); --_line: var(--pk-line, #e4e9ee);
  --_surface: var(--pk-surface, #fff); --_paper: var(--pk-paper, #f3f9ff); --_accent: var(--pk-accent, #0a0a0a);
  --_accent-ink: var(--pk-accent-ink, #fff); --_sky: var(--pk-progress, #00a3ff); --_soft: var(--pk-accent-soft, #e5f5ff);
  --_bad: var(--pk-bad, #d92d20); --_good: #1f9d55; --_pixel: var(--pk-pixel, ui-monospace, monospace);
  --_display: var(--pk-display, inherit); --_spring: cubic-bezier(.3, 1.5, .5, 1); --_ease: cubic-bezier(.2, .8, .2, 1);
  --_dither: repeating-conic-gradient(color-mix(in srgb, var(--_sky) 45%, transparent) 0 25%, transparent 0 50%) 0 0 / 6px 6px;
}
.pkc-card {
  position: relative; display: grid; gap: 18px; width: 100%; padding: 24px;
  border: 1px solid var(--_line); border-radius: var(--pk-radius-lg, 24px);
  background: var(--_surface); color: var(--_ink); font: inherit; overflow: hidden;
  box-shadow: 0 1px 0 rgb(0 0 0 / .03), 0 18px 40px -24px rgb(0 60 120 / .35);
  animation: pkc-in .5s var(--_ease) both;
}
.pkc-card *, .pkc-wallet * { box-sizing: border-box; }
.pkc-card p, .pkc-card h3, .pkc-card ol, .pkc-card ul, .pkc-card dl { margin: 0; }
.pkc-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.pkc-title { font-family: var(--_display); font-style: italic; font-size: 1.6rem; font-weight: 400; line-height: 1.1; }
.pkc-muted { color: var(--_muted); font-size: .875rem; line-height: 1.6; }
.pkc-eyebrow { font-family: var(--_pixel); font-size: .72rem; color: var(--_muted); letter-spacing: .02em; }
.pkc-tag {
  display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px; border-radius: 999px;
  background: var(--_soft); color: var(--_ink); font-family: var(--_pixel); font-size: .68rem; text-transform: capitalize;
}
.pkc-tag::before { content: ''; width: 6px; height: 6px; background: var(--_sky); }
.pkc-tag[data-live="true"]::before { animation: pkc-blink 1s steps(2) infinite; }
.pkc-error { color: var(--_bad); font-size: .875rem; animation: pkc-shake .4s steps(4); }
.pkc-link { color: var(--_ink); font-size: .875rem; text-decoration-color: var(--_sky); text-decoration-thickness: 2px; text-underline-offset: 4px; transition: color .2s; }
.pkc-link:hover { color: var(--_sky); }
.pkc-link::after { content: ' ↗'; display: inline-block; transition: transform .3s var(--_spring); }
.pkc-link:hover::after { transform: translate(2px, -2px); }

/* buttons */
.pkc-button {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 52px; padding: 0 22px; border: 1px solid transparent; border-radius: 999px;
  background: var(--_accent); color: var(--_accent-ink); font: inherit; font-weight: 600; cursor: pointer;
  transition: transform .25s var(--_spring), box-shadow .25s, background-color .2s;
}
.pkc-button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 4px 4px 0 var(--_sky); }
.pkc-button:active:not(:disabled) { transform: translateY(1px) scale(.97); box-shadow: 0 0 0 var(--_sky); }
.pkc-button:disabled { opacity: .55; cursor: default; }
.pkc-button:focus-visible, .pkc-link:focus-visible, .pkc-icon-button:focus-visible, .pkc-hold:focus-visible { outline: 3px solid var(--_sky); outline-offset: 3px; }
.pkc-button--quiet { background: transparent; color: var(--_ink); border-color: var(--_line); }
.pkc-icon-button {
  display: inline-grid; place-items: center; width: 40px; height: 40px; border: 1px solid var(--_line); border-radius: 999px;
  background: var(--_surface); color: var(--_ink); font: inherit; font-size: 1.1rem; cursor: pointer;
  transition: transform .25s var(--_spring), background-color .2s, border-color .2s;
}
.pkc-icon-button:hover:not(:disabled) { border-color: var(--_ink); transform: translateY(-1px); }
.pkc-icon-button:active:not(:disabled) { transform: scale(.88); }
.pkc-icon-button:disabled { opacity: .4; cursor: default; }

/* press-and-hold confirm: deliberate, never accidental */
.pkc-hold {
  --p: 0; position: relative; display: grid; place-items: center; width: 100%; min-height: 58px; padding: 0 22px;
  border: 0; border-radius: 999px; overflow: hidden; isolation: isolate; cursor: pointer; touch-action: none; user-select: none;
  background: var(--_accent); color: var(--_accent-ink); font: inherit; font-weight: 600;
  transition: transform .25s var(--_spring), box-shadow .25s;
}
.pkc-hold::before {
  content: ''; position: absolute; inset: 0; z-index: -1; transform-origin: left;
  transform: scaleX(var(--p)); background: var(--_dither), var(--_sky);
}
.pkc-hold:hover:not(:disabled) { box-shadow: 4px 4px 0 var(--_sky); transform: translateY(-2px); }
.pkc-hold[data-holding="true"] { transform: scale(.98); box-shadow: 0 0 0 4px var(--_soft); }
.pkc-hold:disabled { cursor: progress; }
.pkc-hold[data-state="busy"]::before { transform: scaleX(1); animation: pkc-dither 0.6s steps(3) infinite; }
.pkc-hold[data-state="done"] { background: var(--_good); cursor: default; }
.pkc-hold[data-state="done"]::before { display: none; }
.pkc-hold__label { display: inline-flex; align-items: center; gap: 10px; }
.pkc-hold__hint { font-family: var(--_pixel); font-size: .66rem; opacity: .7; }
.pkc-hold__key { display: inline-grid; place-items: center; width: 22px; height: 22px; border: 1.5px solid currentColor; border-radius: 6px; font-size: .7rem; animation: pkc-press 1.8s var(--_ease) infinite; }
.pkc-dots::after { content: '...'; display: inline-block; width: 3ch; overflow: hidden; vertical-align: bottom; animation: pkc-type 1s steps(4) infinite; }

/* money */
.pkc-total { display: flex; align-items: baseline; gap: 10px; font-size: clamp(2.6rem, 9vw, 3.4rem); font-weight: 600; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1; }
.pkc-total small, .pkc-amount small { font-size: .9rem; font-weight: 500; letter-spacing: 0; color: var(--_muted); }
.pkc-amount { display: flex; align-items: baseline; gap: 8px; font-size: 2.2rem; font-weight: 600; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
.pkc-digits { display: inline-flex; overflow: hidden; }
.pkc-digits span { display: inline-block; animation: pkc-roll .55s var(--_spring) both; animation-delay: calc(var(--i) * 45ms); }
.pkc-lines { list-style: none; padding: 0; display: grid; gap: 10px; padding-top: 16px; border-top: 1px dashed var(--_line); font-size: .9rem; }
.pkc-lines li { display: flex; justify-content: space-between; gap: 12px; }
.pkc-lines li > span:first-child { color: var(--_muted); }
.pkc-free { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; }
.pkc-free::before { content: ''; width: 8px; height: 8px; background: var(--_good); }

/* phase strip */
.pkc-phases { list-style: none; padding: 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.pkc-phases li { display: grid; gap: 7px; font-family: var(--_pixel); font-size: .66rem; color: var(--_muted); transition: color .3s; }
.pkc-phases li::before { content: ''; height: 6px; border-radius: 2px; background: var(--_line); transition: background-color .3s; }
.pkc-phases li[data-state="active"] { color: var(--_ink); }
.pkc-phases li[data-state="active"]::before { background: var(--_dither), var(--_sky); animation: pkc-dither .5s steps(3) infinite; }
.pkc-phases li[data-state="done"] { color: var(--_ink); }
.pkc-phases li[data-state="done"]::before { background: var(--_ink); animation: pkc-pop .35s var(--_spring); }

/* disclosure */
.pkc-why { border-radius: 16px; background: var(--_paper); font-size: .85rem; }
.pkc-why summary { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; cursor: pointer; list-style: none; font-weight: 500; }
.pkc-why summary::-webkit-details-marker { display: none; }
.pkc-why summary::after { content: '+'; font-family: var(--_pixel); transition: transform .3s var(--_spring); }
.pkc-why[open] summary::after { transform: rotate(45deg); }
.pkc-why[open] > :not(summary) { animation: pkc-in .35s var(--_ease); }
.pkc-why .pkc-details { padding: 0 16px 14px; }

.pkc-details { display: grid; gap: 10px; }
.pkc-details div { display: flex; justify-content: space-between; gap: 12px; }
.pkc-details dt { color: var(--_muted); }
.pkc-details dd { margin: 0; text-align: right; overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
.pkc-mono { font-family: ui-monospace, 'Geist Mono', monospace; font-size: .8em; }

/* points: coupons are tickets you tear off; unaffordable ones stay locked */
.pkc-was { margin-left: 4px; font-size: 1rem; font-weight: 500; color: var(--_muted); letter-spacing: 0; animation: pkc-in .3s var(--_ease); }
.pkc-earn { font-family: var(--_pixel); font-size: .78rem; color: var(--_sky); }
.pkc-coupons { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 8px; margin: 0; padding: 0; border: 0; min-width: 0; }
.pkc-coupons legend { margin-bottom: 8px; padding: 0; }
.pkc-coupon {
  position: relative; display: grid; gap: 4px; padding: 12px 14px; border: 1.5px dashed var(--_line); border-radius: 14px;
  background: var(--_surface); color: var(--_ink); font: inherit; text-align: left; cursor: pointer;
  transition: transform .3s var(--_spring), border-color .2s, background-color .2s, box-shadow .25s;
}
.pkc-coupon::before, .pkc-coupon::after { content: ''; position: absolute; top: 50%; width: 12px; height: 12px; margin-top: -6px; border-radius: 50%; background: var(--pk-paper, #f3f9ff); border: 1.5px dashed var(--_line); }
.pkc-coupon::before { left: -7px; clip-path: inset(0 0 0 50%); }
.pkc-coupon::after { right: -7px; clip-path: inset(0 50% 0 0); }
.pkc-coupon:hover:not(:disabled) { transform: translateY(-2px) rotate(-1deg); border-color: var(--_ink); }
.pkc-coupon:active:not(:disabled) { transform: scale(.96); }
.pkc-coupon[aria-pressed="true"] { border-style: solid; border-color: var(--_ink); background: var(--_dither), var(--_soft); box-shadow: 4px 4px 0 var(--_sky); animation: pkc-pop .35s var(--_spring); }
.pkc-coupon:disabled { cursor: not-allowed; opacity: .55; }
.pkc-coupons:disabled .pkc-coupon { cursor: progress; }
.pkc-coupon__name { font-weight: 600; font-size: .9rem; }
.pkc-coupon__cost { font-family: var(--_pixel); font-size: .66rem; color: var(--_muted); }
.pkc-coupon[aria-pressed="true"] .pkc-coupon__cost { color: var(--_ink); }

/* success burst */
.pkc-burst { position: absolute; left: 50%; bottom: 52px; width: 0; height: 0; pointer-events: none; }
.pkc-burst i { position: absolute; width: 8px; height: 8px; background: var(--_sky); animation: pkc-burst .8s steps(8) forwards; }
.pkc-burst i:nth-child(3n) { background: var(--_ink); }
.pkc-burst i:nth-child(4n) { background: var(--pk-progress-soft, #7ccfff); width: 6px; height: 6px; }

/* payment status: a pixel runner hops between stations */
.pkc-track { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); padding-top: 26px; }
.pkc-track__rail { position: absolute; left: 12.5%; right: 12.5%; top: 34px; height: 4px; background: var(--_line); }
.pkc-track__fill { position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--at) * 100%); background: var(--_ink); transition: width .8s steps(8); }
.pkc-track__runner {
  position: absolute; top: 0; left: calc(12.5% + var(--at) * 75%); width: 16px; height: 16px; margin-left: -8px;
  background: var(--_sky); box-shadow: 4px 4px 0 var(--_ink); transition: left .8s steps(8); animation: pkc-hop .9s steps(3) infinite;
}
.pkc-track[data-failed="true"] .pkc-track__runner { background: var(--_bad); animation: none; }
.pkc-track__runner--done { animation: pkc-pop .5s var(--_spring); }
.pkc-station { position: relative; display: grid; justify-items: center; gap: 10px; text-align: center; font-family: var(--_pixel); font-size: .66rem; color: var(--_muted); }
.pkc-station::before { content: ''; width: 12px; height: 12px; margin-top: 2px; background: var(--_surface); border: 2px solid var(--_line); transition: background-color .3s, border-color .3s, transform .4s var(--_spring); }
.pkc-station[data-state="done"] { color: var(--_ink); }
.pkc-station[data-state="done"]::before { background: var(--_ink); border-color: var(--_ink); transform: rotate(45deg); }
.pkc-station[data-state="active"] { color: var(--_ink); }
.pkc-station[data-state="active"]::before { border-color: var(--_sky); background: var(--_soft); }
.pkc-note { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 14px; background: var(--_paper); font-size: .875rem; }
.pkc-note b { font-weight: 600; }
.pkc-note time { margin-left: auto; font-family: var(--_pixel); font-size: .7rem; color: var(--_muted); font-variant-numeric: tabular-nums; }

/* receipt: prints line by line, then gets stamped */
.pkc-receipt { gap: 16px; padding-bottom: 34px; animation: pkc-print 1s steps(10) both; }
.pkc-receipt::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -1px; height: 14px;
  background: radial-gradient(circle at 10px 14px, var(--pk-paper, #f3f9ff) 7px, transparent 7.5px) 0 0 / 20px 14px repeat-x;
}
.pkc-receipt__head { display: grid; gap: 4px; padding-bottom: 14px; border-bottom: 1px dashed var(--_line); }
.pkc-receipt .pkc-details div { animation: pkc-in .3s var(--_ease) both; animation-delay: calc(.6s + var(--i, 0) * 70ms); }
.pkc-stamp {
  position: absolute; right: 18px; top: 20px; padding: 6px 12px; border: 3px solid var(--_good); border-radius: 8px;
  color: var(--_good); font-family: var(--_pixel); font-size: .9rem; letter-spacing: .08em; transform: rotate(-10deg);
  animation: pkc-stamp .45s 1.1s var(--_spring) both; mix-blend-mode: multiply;
}
.pkc-copy { border: 0; background: none; padding: 0 0 0 6px; font: inherit; color: var(--_muted); cursor: pointer; transition: color .2s, transform .25s var(--_spring); }
.pkc-copy:hover { color: var(--_ink); }
.pkc-copy:active { transform: scale(.85); }
.pkc-copy[data-copied="true"] { color: var(--_good); }

/* product card */
.pkc-product { gap: 14px; padding: 12px 12px 18px; }
.pkc-product__art {
  position: relative; aspect-ratio: 4 / 3; border-radius: 16px; overflow: hidden; background: var(--_paper);
  display: grid; place-items: center;
}
.pkc-product__art img { width: 100%; height: 100%; object-fit: cover; transition: transform .6s var(--_ease); }
.pkc-product:hover .pkc-product__art img, .pkc-product:hover .pkc-sprite { transform: scale(1.06); }
.pkc-sprite { display: grid; grid-template-columns: repeat(7, 1fr); width: 46%; aspect-ratio: 1; image-rendering: pixelated; transition: transform .6s var(--_spring); }
.pkc-sprite i { aspect-ratio: 1; }
.pkc-product__body { display: grid; gap: 6px; padding: 0 6px; }
.pkc-product__foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0 6px; }
.pkc-product__price { font-size: 1.25rem; font-weight: 600; font-variant-numeric: tabular-nums; }
.pkc-product__price small { font-size: .75rem; color: var(--_muted); font-weight: 500; }
.pkc-soldout { position: absolute; inset: auto 0 14px; margin: auto; width: max-content; padding: 6px 12px; background: var(--_ink); color: #fff; font-family: var(--_pixel); font-size: .7rem; transform: rotate(-4deg); }
.pkc-stepper {
  display: inline-flex; align-items: center; gap: 4px; padding: 4px; border-radius: 999px; background: var(--_ink); color: var(--_accent-ink);
  animation: pkc-morph .4s var(--_spring);
}
.pkc-stepper button { width: 36px; height: 36px; border: 0; border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 1.1rem; cursor: pointer; transition: background-color .2s, transform .2s var(--_spring); }
.pkc-stepper button:hover:not(:disabled) { background: rgb(255 255 255 / .16); }
.pkc-stepper button:active:not(:disabled) { transform: scale(.82); }
.pkc-stepper button:disabled { opacity: .35; }
.pkc-stepper output { min-width: 2ch; text-align: center; font-variant-numeric: tabular-nums; font-weight: 600; }
.pkc-stepper output span { display: inline-block; animation: pkc-roll .35s var(--_spring); }
.pkc-plus { position: absolute; right: 26px; bottom: 54px; font-family: var(--_pixel); font-size: .8rem; color: var(--_sky); pointer-events: none; animation: pkc-float .8s steps(6) forwards; }

/* installment plan */
.pkc-schedule { display: grid; grid-template-columns: repeat(var(--n), 1fr); gap: 6px; }
.pkc-slot {
  display: grid; gap: 8px; padding: 0; border: 0; background: none; font: inherit; color: var(--_muted); text-align: left; cursor: pointer;
  font-family: var(--_pixel); font-size: .62rem;
}
.pkc-slot::before {
  content: ''; height: calc(18px + var(--h) * 34px); border-radius: 6px; background: var(--_soft);
  transition: background-color .25s, transform .35s var(--_spring); transform-origin: bottom;
  animation: pkc-grow .5s var(--_spring) both; animation-delay: calc(var(--i) * 60ms);
}
.pkc-slot[data-kind="now"]::before { background: var(--_dither), var(--_sky); }
.pkc-slot:hover::before, .pkc-slot[aria-pressed="true"]::before { background: var(--_ink); transform: scaleY(1.06); }
.pkc-slot[aria-pressed="true"] { color: var(--_ink); }
.pkc-schedule[data-done="true"] .pkc-slot::before { background: var(--_ink); }
.pkc-slot-note { min-height: 1.6em; font-size: .875rem; }
.pkc-slot-note span { display: inline-block; animation: pkc-in .25s var(--_ease); }

/* wallet */
.pkc-wallet { position: relative; display: inline-flex; flex-direction: column; align-items: flex-start; gap: 10px; color: var(--_ink); font: inherit; }
.pkc-connect .pkc-plug { display: inline-block; transition: transform .35s var(--_spring); }
.pkc-connect:hover .pkc-plug { transform: rotate(-20deg) translateX(-2px); }
.pkc-pill {
  display: inline-flex; align-items: center; gap: 10px; padding: 5px 14px 5px 5px; border: 1px solid var(--_line); border-radius: 999px;
  background: var(--_surface); color: var(--_ink); font: inherit; font-weight: 500; cursor: pointer;
  box-shadow: 0 10px 24px -16px rgb(0 60 120 / .5); transition: transform .25s var(--_spring), border-color .2s, box-shadow .25s;
  animation: pkc-morph .45s var(--_spring);
}
.pkc-pill:hover { border-color: var(--_ink); transform: translateY(-2px); box-shadow: 4px 4px 0 var(--_sky); }
.pkc-pill[aria-expanded="true"] { border-color: var(--_ink); }
.pkc-pill__chev { font-size: .7rem; transition: transform .3s var(--_spring); }
.pkc-pill[aria-expanded="true"] .pkc-pill__chev { transform: rotate(180deg); }
.pkc-pill__dot { width: 8px; height: 8px; background: var(--_good); animation: pkc-blink 1.4s steps(2) infinite; }
.pkc-pill__dot[data-warn="true"] { background: #f59e0b; }
.pkc-face { display: grid; grid-template-columns: repeat(5, 1fr); width: 30px; height: 30px; padding: 3px; border-radius: 999px; background: var(--_paper); image-rendering: pixelated; }
.pkc-menu {
  position: absolute; top: calc(100% - 4px); left: 0; z-index: 5; display: grid; min-width: 220px; padding: 6px; margin-top: 8px;
  border: 1px solid var(--_line); border-radius: 18px; background: var(--_surface); box-shadow: 8px 8px 0 color-mix(in srgb, var(--_sky) 35%, transparent);
  transform-origin: top left; animation: pkc-menu .3s var(--_spring);
}
.pkc-menu button { display: flex; justify-content: space-between; gap: 12px; padding: 10px 12px; border: 0; border-radius: 12px; background: none; font: inherit; font-size: .9rem; color: var(--_ink); text-align: left; cursor: pointer; transition: background-color .15s, padding-left .25s var(--_spring); }
.pkc-menu button:hover, .pkc-menu button:focus-visible { background: var(--_paper); padding-left: 16px; outline: none; }
.pkc-menu button span { font-family: var(--_pixel); font-size: .66rem; color: var(--_muted); }
.pkc-menu .pkc-menu__danger { color: var(--_bad); }

.pkc-skeleton { height: 14px; border-radius: 6px; background: linear-gradient(90deg, var(--_paper), var(--_soft), var(--_paper)) 0 0 / 200% 100%; animation: pkc-shimmer 1.2s linear infinite; }

@keyframes pkc-in { from { opacity: 0; transform: translateY(10px); } }
@keyframes pkc-roll { from { opacity: 0; transform: translateY(80%); } }
@keyframes pkc-pop { 0% { transform: scale(.4); } 70% { transform: scale(1.15); } }
@keyframes pkc-blink { 50% { opacity: .2; } }
@keyframes pkc-dither { to { background-position: 6px 0, 0 0; } }
@keyframes pkc-type { from { width: 0; } }
@keyframes pkc-press { 0%, 60%, 100% { transform: translateY(0); } 70% { transform: translateY(2px); box-shadow: inset 0 -1px 0 currentColor; } }
@keyframes pkc-burst { from { transform: translate(0, 0); opacity: 1; } to { transform: translate(var(--x), var(--y)); opacity: 0; } }
@keyframes pkc-hop { 50% { transform: translateY(-5px); } }
@keyframes pkc-print { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes pkc-stamp { from { opacity: 0; transform: rotate(-10deg) scale(2.2); } }
@keyframes pkc-float { to { transform: translateY(-34px); opacity: 0; } }
@keyframes pkc-morph { from { transform: scale(.85); opacity: .4; } }
@keyframes pkc-grow { from { transform: scaleY(0); } }
@keyframes pkc-menu { from { opacity: 0; transform: scale(.9) translateY(-6px); } }
@keyframes pkc-shake { 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
@keyframes pkc-shimmer { to { background-position: -200% 0; } }
@media (prefers-reduced-motion: reduce) {
  .pkc-card, .pkc-card *, .pkc-wallet, .pkc-wallet * { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}
